/**
 * MailerLite Node - Version 2
 * Discriminator: resource=subscriber, operation=get
 */


interface Credentials {
  mailerLiteApi: CredentialReference;
}

/** Get an subscriber */
export type MailerLiteV2SubscriberGetParams = {
  resource: 'subscriber';
  operation: 'get';
/**
 * Email of subscriber to get
 */
    subscriberId: string | Expression<string>;
};

export type MailerLiteV2SubscriberGetOutput = {
  id?: number;
  name?: string;
  email?: string;
  sent?: number;
  opened?: number;
  clicked?: number;
  type?: string;
  country_id?: string;
  signup_ip?: null;
  signup_timestamp?: null;
  fields?: Array<{
    key: string;
    value: string;
    type: string;
  }>;
  date_unsubscribe?: null;
  date_created?: string;
  date_updated?: string;
};

export type MailerLiteV2SubscriberGetNode = {
  type: 'n8n-nodes-base.mailerLite';
  version: 2;
  config: NodeConfig<MailerLiteV2SubscriberGetParams> & { credentials?: Credentials };
  output?: Items<MailerLiteV2SubscriberGetOutput>;
};